# -- .grad: subgradient of matrix_frac(X, P) = X^T P^-1 X ---------
## CVXPY SOURCE: atoms/matrix_frac.py:53-91 (matrix_frac._grad).
## Two args: X (vector / matrix) and P (PSD matrix).
##   d/dX = (P^-1 + P^-T) X
##   d/dP = - (P^-1 X X^T P^-1)^T   (already symmetrised in CVXPY)
## NULL on both args when P is singular.
method(.grad, MatrixFrac) <- function(x, values, ...) {
  X <- as.matrix(values[[1L]])
  P <- as.matrix(values[[2L]])
  P_inv <- tryCatch(solve(P), error = function(e) NULL)
  if (is.null(P_inv)) return(list(NULL, NULL))

  ## d/dX = (P^-1 + P^-T) X
  DX <- (P_inv + t(P_inv)) %*% X
  rows_X <- as.integer(prod(x@args[[1L]]@shape))

  ## d/dP = -(P^-1 X X^T P^-1)^T  (CVXPY's exact form, see lines 80-83)
  DP <- P_inv %*% X
  DP <- DP %*% t(X)
  DP <- DP %*% P_inv
  DP <- -t(DP)
  ## CVXPY then transposes again before raveling: t(DP).ravel(order='F')
  ## i.e. emits the *original* (untransposed) entries in column-major.
  rows_P <- as.integer(prod(x@args[[2L]]@shape))

  list(
    .dense_to_csc_vector(as.numeric(DX), rows_X),
    .dense_to_csc_vector(as.numeric(t(DP)), rows_P)
  )
}

# ==================================================================
# Convenience function
# ==================================================================

#' Matrix fractional function
#'
#' Computes \eqn{\mathrm{trace}(X^T P^{-1} X)}. If P is a constant matrix, uses
#' a QuadForm shortcut for efficiency.
#'
#' @param X A matrix expression (n by m)
#' @param P A square matrix expression (n by n), must be PSD
#' @returns An expression representing \eqn{\mathrm{trace}(X^T P^{-1} X)}
#' @export
matrix_frac <- function(X, P) {
  ## CVXPY: matrix_frac.py lines 147-153
  ## If P is a constant numeric matrix, shortcut via QuadForm
  if (is.matrix(P) && !inherits(P, "Expression") && !.s7_is(P, Expression)) {
    invP <- solve(P)
    return(quad_form(X, (invP + t(invP)) / 2.0))
  }
  MatrixFrac(X, P)
}
